)

type NetworkStatus int32

type PartitionAwareLeader struct {
	nodeID      string
	networkUp   bool
	cancelWork  context.CancelFunc
}

func (l *PartitionAwareLeader) Run(ctx context.Context) {
	workCtx, cancel := context.WithCancel(ctx)
	l.cancelWork = cancel

	// 1. Рабочий бизнес-цикл
	go func() {
		for {
			select {
			case <-workCtx.Done():
				fmt.Printf("🛑 [%s] Бизнес-процесс остановлен по сигналу отмены контекста!\n", l.nodeID)
				return
			default:
				fmt.Printf("💼 [%s] Лидер выполняет полезную работу...\n", l.nodeID)
				time.Sleep(30 * time.Millisecond)
			}
		}
	}()

	// 2. Сторожевой таймер проверки аренды в etcd
	go func() {
		ticker := time.NewTicker(40 * time.Millisecond)
		defer ticker.Stop()

		for {
			select {
			case <-workCtx.Done():
				return
			case <-ticker.C:
				if !l.networkUp {
					fmt.Printf("🚨 [%s] ТРЕВОГА: Потеряна связь с etcd! Немедленно отменяем рабочий контекст!\n", l.nodeID)
					l.cancelWork()
					return
				}
			}
		}
	}()
}

func main() {
	leader := &PartitionAwareLeader{
		nodeID:    "Node-A-OriginalLeader",
		networkUp: true,
	}

	ctx := context.Background()
	leader.Run(ctx)

	// Лидер работает 70 мс в нормальной сети
	time.Sleep(70 * time.Millisecond)

	// Имитируем сетевой сплит (iptables DROP к etcd)
	fmt.Println("\n✂️ [Сетевой сплит] Связь с etcd оборвана!")
	leader.networkUp = false

	// Даем время сторожевому таймеру отработать
	time.Sleep(60 * time.Millisecond)
}

package main

import (
	"fmt"
	"sync"
	"time"
)

type K8sLeaseObject struct {
	Name                 string
	Namespace            string
	HolderIdentity       string
	LeaseDurationSeconds int
	AcquireTime          time.Time
	RenewTime            time.Time
	LeaderTransitions    int
}

type K8sApiServerLeaseStore struct {
	mu    sync.Mutex
	lease *K8sLeaseObject
}

func (s *K8sApiServerLeaseStore) TryAcquireOrRenew(candidatePod string, durationSec int) bool {
	s.mu.Lock()
	defer s.mu.Unlock()

	now := time.Now()

	// 1. Создание или первичный захват
	if s.lease == nil {
		s.lease = &K8sLeaseObject{
			Name:                 "ingress-controller-lock",
			Namespace:            "ingress-nginx",
			HolderIdentity:       candidatePod,
			LeaseDurationSeconds: durationSec,
			AcquireTime:          now,
			RenewTime:            now,
			LeaderTransitions:    1,
		}
		fmt.Printf("📦 [K8s API] Создан Lease! Первый лидер: %s\n", candidatePod)
		return true
	}

	// 2. Продление действующим лидером
	if s.lease.HolderIdentity == candidatePod {
		s.lease.RenewTime = now
		return true
	}

	// 3. Проверка просрочки аренды старого лидера
	expireBoundary := s.lease.RenewTime.Add(time.Duration(s.lease.LeaseDurationSeconds) * time.Second)
	if now.After(expireBoundary) {
		old := s.lease.HolderIdentity
		s.lease.HolderIdentity = candidatePod
		s.lease.AcquireTime = now
		s.lease.RenewTime = now
		s.lease.LeaderTransitions++
		fmt.Printf("🔄 [K8s API] Lease истек (%s)! Переход права лидерства к %s (Переходов: %d)\n",
			old, candidatePod, s.lease.LeaderTransitions)
		return true
	}

	return false
}

func main() {
	apiServer := &K8sApiServerLeaseStore{}

	pod1 := "ingress-nginx-controller-6f8599-alpha"
	pod2 := "ingress-nginx-controller-6f8599-beta"

	// Pod 1 захватывает Lease с длительностью 1 секунда
	apiServer.TryAcquireOrRenew(pod1, 1)

	// Pod 2 пытается захватить — отказ
	ok2 := apiServer.TryAcquireOrRenew(pod2, 1)
	fmt.Printf("[Pod 2] Попытка захвата активного Lease: %v\n", ok2)

	// Ждем истечения LeaseDuration (1.1 сек)
	time.Sleep(1100 * time.Millisecond)

	// Pod 2 повторяет попытку после истечения — победа!
	ok2After := apiServer.TryAcquireOrRenew(pod2, 1)
	fmt.Printf("[Pod 2] Попытка после истечения Lease: %v\n", ok2After)
}

package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

var (
	ErrPartitionDetected = errors.New("network partition detected: keepalive stalled")
	ErrNotLeader          = errors.New("node is not leading")
)

type LeaseStatus struct {
	ID        int64
	TTL       time.Duration
	LastAlive time.Time
}

type NodeGuard struct {
	mu           sync.RWMutex
	nodeID       string
	isLeader     bool
	lease        LeaseStatus
	cancelLeader context.CancelFunc
}

func NewNodeGuard(nodeID string, ttl time.Duration) *NodeGuard {
	return &NodeGuard{
		nodeID: nodeID,
		lease: LeaseStatus{
			ID:  1001,
			TTL: ttl,
		},
	}
}

func (g *NodeGuard) AssumeLeadership(parent context.Context) context.Context {
	g.mu.Lock()
	defer g.mu.Unlock()

	ctx, cancel := context.WithCancel(parent)
	g.isLeader = true
	g.lease.LastAlive = time.Now()
	g.cancelLeader = cancel
	return ctx
}

func (g *NodeGuard) OnKeepAliveResponse() {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.lease.LastAlive = time.Now()
}

func (g *NodeGuard) MonitorPartition(ctx context.Context, checkInterval time.Duration) {
	ticker := time.NewTicker(checkInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			g.mu.Lock()
			if !g.isLeader {
				g.mu.Unlock()
				continue
			}

			// Если ответ keepalive не приходил дольше половины TTL,
			// считаем себя отрезанными от большинства etcd и сбрасываем полномочия
			elapsed := time.Since(g.lease.LastAlive)
			if elapsed > g.lease.TTL/2 {
				fmt.Printf("[%s] WARNING: Partition suspected! No keepalive for %v (TTL=%v). Stepping down!\n",
					g.nodeID, elapsed, g.lease.TTL)
				g.isLeader = false
				if g.cancelLeader != nil {
					g.cancelLeader()
				}
				g.mu.Unlock()
				return
			}
			g.mu.Unlock()
		}
	}
}

func (g *NodeGuard) ExecuteMutation(action func() error) error {
	g.mu.RLock()
	defer g.mu.RUnlock()

	if !g.isLeader {
		return ErrNotLeader
	}
	if time.Since(g.lease.LastAlive) > g.lease.TTL/2 {
		return ErrPartitionDetected
	}
	return action()
}

func main() {
	guard := NewNodeGuard("node-A-minority", 4*time.Second)
	leaderCtx := guard.AssumeLeadership(context.Background())

	go guard.MonitorPartition(leaderCtx, 500*time.Millisecond)

	// Имитация успешных keepalive в течение 1 секунды
	for i := 0; i < 2; i++ {
		time.Sleep(500 * time.Millisecond)
		guard.OnKeepAliveResponse()
		fmt.Println("[node-A] Keepalive renewed successfully")
	}

	// Имитация сетевой изоляции (iptables DROP): ответы перестают приходить
	fmt.Println("[node-A] Network partition occurs (iptables DROP etcd traffic)...")

	// Пытаемся выполнять операции
	for i := 0; i < 6; i++ {
		time.Sleep(500 * time.Millisecond)
		err := guard.ExecuteMutation(func() error {
			fmt.Println("[node-A] Critical state mutation executed")
			return nil
		})
		if err != nil {
			fmt.Printf("[node-A] Operation rejected: %v\n", err)
		}
	}
}

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type LeaderCallbacks struct {
	OnStartedLeading func(ctx context.Context)
	OnStoppedLeading func()
	OnNewLeader      func(identity string)
}

type ElectionRunner struct {
	nodeID    string
	callbacks LeaderCallbacks
	isLeading atomic.Bool
}

func NewElectionRunner(nodeID string, callbacks LeaderCallbacks) *ElectionRunner {
	return &ElectionRunner{
		nodeID:    nodeID,
		callbacks: callbacks,
	}
}

func (r *ElectionRunner) RunLeaderLifecycle(parent context.Context, duration time.Duration, triggerPanic bool) {
	ctx, cancel := context.WithCancel(parent)
	defer cancel()

	r.isLeading.Store(true)
	fmt.Printf("[%s] Elected leader! Invoking OnStartedLeading...\n", r.nodeID)

	// Гарантируем вызов OnStoppedLeading даже при панике
	defer func() {
		r.isLeading.Store(false)
		if p := recover(); p != nil {
			fmt.Printf("[%s] PANIC intercepted inside OnStartedLeading: %v\n", r.nodeID, p)
		}
		if r.callbacks.OnStoppedLeading != nil {
			fmt.Printf("[%s] Invoking OnStoppedLeading cleanup hook...\n", r.nodeID)
			r.callbacks.OnStoppedLeading()
		}
	}()

	if r.callbacks.OnStartedLeading != nil {
		done := make(chan struct{})
		go func() {
			defer close(done)
			defer func() {
				if p := recover(); p != nil {
					fmt.Printf("[%s] Background leading panic: %v\n", r.nodeID, p)
					cancel()
				}
			}()

			if triggerPanic {
				time.Sleep(300 * time.Millisecond)
				panic("unhandled nil pointer dereference in business logic")
			}

			// Имитация полезной работы
			select {
			case <-ctx.Done():
			case <-time.After(duration):
			}
		}()

		select {
		case <-ctx.Done():
		case <-done:
		}
	}
}

func main() {
	var stoppedCalled atomic.Bool
	var wg sync.WaitGroup

	callbacks := LeaderCallbacks{
		OnStartedLeading: func(ctx context.Context) {
			fmt.Println("[App] Starting background cron and transaction processors...")
		},
		OnStoppedLeading: func() {
			stoppedCalled.Store(true)
			fmt.Println("[App] Flushed pending buffers, closed leader TCP sockets.")
		},
		OnNewLeader: func(identity string) {
			fmt.Printf("[App] Discovered active leader: %s\n", identity)
		},
	}

	runner := NewElectionRunner("node-k8s-pod-1", callbacks)

	wg.Add(1)
	go func() {
		defer wg.Done()
		runner.RunLeaderLifecycle(context.Background(), 2*time.Second, true)
	}()

	wg.Wait()
	fmt.Printf("Was OnStoppedLeading called successfully after panic? %v\n", stoppedCalled.Load())
}

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type CronJob struct {
	Name     string
	Interval time.Duration
	LastRun  time.Time
	Action   func(ctx context.Context) error
}

type DistributedScheduler struct {
	mu           sync.Mutex
	nodeID       string
	isLeader     bool
	jobs         []*CronJob
	cancelActive context.CancelFunc
	taskCounter  atomic.Int64
}

func NewDistributedScheduler(nodeID string) *DistributedScheduler {
	return &DistributedScheduler{
		nodeID: nodeID,
		jobs:   make([]*CronJob, 0),
	}
}

func (s *DistributedScheduler) RegisterJob(job *CronJob) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.jobs = append(s.jobs, job)
}

func (s *DistributedScheduler) OnElected(parent context.Context) {
	s.mu.Lock()
	defer s.mu.Unlock()

	s.isLeader = true
	ctx, cancel := context.WithCancel(parent)
	s.cancelActive = cancel

	fmt.Printf("[%s] Scheduler ACTIVATED. Watching %d jobs...\n", s.nodeID, len(s.jobs))

	for _, job := range s.jobs {
		go s.runJobLoop(ctx, job)
	}
}

func (s *DistributedScheduler) OnDemoted() {
	s.mu.Lock()
	defer s.mu.Unlock()

	if !s.isLeader {
		return
	}
	s.isLeader = false
	if s.cancelActive != nil {
		s.cancelActive()
		s.cancelActive = nil
	}
	fmt.Printf("[%s] Scheduler PAUSED. Cancelled active tickers.\n", s.nodeID)
}

func (s *DistributedScheduler) runJobLoop(ctx context.Context, job *CronJob) {
	ticker := time.NewTicker(job.Interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case now := <-ticker.C:
			s.mu.Lock()
			if !s.isLeader {
				s.mu.Unlock()
				return
			}
			job.LastRun = now
			s.mu.Unlock()

			count := s.taskCounter.Add(1)
			fmt.Printf("[%s] Executing job '%s' (Run #%d) at %s\n",
				s.nodeID, job.Name, count, now.Format("15:04:05.000"))

			if err := job.Action(ctx); err != nil {
				fmt.Printf("[%s] Job '%s' failed: %v\n", s.nodeID, job.Name, err)
			}
		}
	}
}

func main() {
	billingJob := &CronJob{
		Name:     "BillingRollup",
		Interval: 400 * time.Millisecond,
		Action: func(ctx context.Context) error {
			time.Sleep(50 * time.Millisecond)
			return nil
		},
	}

	node1 := NewDistributedScheduler("replica-1")
	node2 := NewDistributedScheduler("replica-2")

	node1.RegisterJob(billingJob)
	node2.RegisterJob(billingJob)

	ctx := context.Background()

	// Реплика 1 становится лидером
	fmt.Println("=== STEP 1: Replica-1 is leading ===")
	node1.OnElected(ctx)
	time.Sleep(1 * time.Second)

	// Failover: Реплика 1 падает, Реплика 2 перехватывает лидерство
	fmt.Println("\n=== STEP 2: Failover to Replica-2 ===")
	node1.OnDemoted()
	node2.OnElected(ctx)
	time.Sleep(1 * time.Second)

	node2.OnDemoted()
	fmt.Println("\nScheduler demonstration finished cleanly.")
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
)

type ClusterState struct {
	isLeader   atomic.Bool
	leaderAddr atomic.Value // string
}

func (s *ClusterState) SetLeader(leading bool, addr string) {
	s.isLeader.Store(leading)
	s.leaderAddr.Store(addr)
}

func LeaderRoutingMiddleware(state *ClusterState, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Безопасные идемпотентные запросы на чтение разрешены на всех репликах
		if r.Method == http.MethodGet || r.Method == http.MethodHead || r.Method == http.MethodOptions {
			w.Header().Set("X-Served-By-Role", "replica")
			next.ServeHTTP(w, r)
			return
		}

		// Мутирующие запросы требуют лидерства
		if state.isLeader.Load() {
			w.Header().Set("X-Served-By-Role", "leader")
			next.ServeHTTP(w, r)
			return
		}

		// Нода является фоловером — перенаправляем на лидера через HTTP 307 Temporary Redirect
		leader, _ := state.leaderAddr.Load().(string)
		if leader == "" {
			http.Error(w, "Cluster leader unavailable, election in progress", http.StatusServiceUnavailable)
			return
		}

		redirectURL := fmt.Sprintf("http://%s%s", leader, r.RequestURI)
		w.Header().Set("Location", redirectURL)
		w.Header().Set("X-Leader-Address", leader)
		w.WriteHeader(http.StatusTemporaryRedirect) // HTTP 307 гарантирует повтор с тем же методом и телом
		fmt.Fprintf(w, "Redirecting mutating request to active leader: %s\n", redirectURL)
	})
}

func main() {
	state := &ClusterState{}

	businessHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		fmt.Fprintf(w, "Mutation [%s %s] committed successfully!\n", r.Method, r.URL.Path)
	})

	router := LeaderRoutingMiddleware(state, businessHandler)

	// Сценарий 1: Нода является фоловером, клиент отправляет POST
	state.SetLeader(false, "10.0.0.12:8080")
	reqPost := httptest.NewRequest(http.MethodPost, "/api/v1/orders", nil)
	rec1 := httptest.NewRecorder()
	router.ServeHTTP(rec1, reqPost)

	fmt.Printf("[Follower] POST status: %d\n", rec1.Code)
	fmt.Printf("[Follower] Location header: %s\n", rec1.Header().Get("Location"))
	fmt.Printf("[Follower] Body: %s", rec1.Body.String())

	// Сценарий 2: Тот же фоловер обрабатывает GET
	reqGet := httptest.NewRequest(http.MethodGet, "/api/v1/orders/42", nil)
	rec2 := httptest.NewRecorder()
	router.ServeHTTP(rec2, reqGet)
	fmt.Printf("\n[Follower] GET status: %d, Role header: %s\n", rec2.Code, rec2.Header().Get("X-Served-By-Role"))

	// Сценарий 3: Нода выиграла выборы и стала лидером
	state.SetLeader(true, "10.0.0.10:8080")
	rec3 := httptest.NewRecorder()
	router.ServeHTTP(rec3, reqPost)
	fmt.Printf("\n[Leader] POST status: %d, Role header: %s\n", rec3.Code, rec3.Header().Get("X-Served-By-Role"))
	fmt.Printf("[Leader] Body: %s", rec3.Body.String())
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type TaskStatus string

const (
	StatusPending   TaskStatus = "PENDING"
	StatusAssigned  TaskStatus = "ASSIGNED"
	StatusCompleted TaskStatus = "COMPLETED"
)

type Task struct {
	ID        string
	Payload   string
	Status    TaskStatus
	WorkerID  string
	Heartbeat time.Time
}

type Coordinator struct {
	mu       sync.Mutex
	leaderID string
	tasks    map[string]*Task
	workers  map[string]time.Time
}

func NewCoordinator(leaderID string) *Coordinator {
	return &Coordinator{
		leaderID: leaderID,
		tasks:    make(map[string]*Task),
		workers:  make(map[string]time.Time),
	}
}

func (c *Coordinator) SubmitTask(id, payload string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.tasks[id] = &Task{
		ID:      id,
		Payload: payload,
		Status:  StatusPending,
	}
}

func (c *Coordinator) RegisterWorkerHeartbeat(workerID string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.workers[workerID] = time.Now()
}

func (c *Coordinator) DispatchTasks() {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now()
	// Ищем живых воркеров (heartbeat < 2s)
	activeWorkers := make([]string, 0)
	for wID, lastBeat := range c.workers {
		if now.Sub(lastBeat) < 2*time.Second {
			activeWorkers = append(activeWorkers, wID)
		}
	}

	if len(activeWorkers) == 0 {
		return
	}

	wIdx := 0
	for _, task := range c.tasks {
		if task.Status == StatusPending {
			worker := activeWorkers[wIdx%len(activeWorkers)]
			wIdx++
			task.Status = StatusAssigned
			task.WorkerID = worker
			task.Heartbeat = now
			fmt.Printf("[%s] Assigned Task %s to Worker %s\n", c.leaderID, task.ID, worker)
		}
	}
}

func (c *Coordinator) ReassignStaleTasks(timeout time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := time.Now()
	for _, task := range c.tasks {
		if task.Status == StatusAssigned {
			lastBeat, workerAlive := c.workers[task.WorkerID]
			if !workerAlive || now.Sub(lastBeat) > timeout {
				fmt.Printf("[%s] Worker %s STALLED for task %s! Reassigning to PENDING...\n",
					c.leaderID, task.WorkerID, task.ID)
				task.Status = StatusPending
				task.WorkerID = ""
			}
		}
	}
}

func main() {
	coord := NewCoordinator("leader-node-alpha")

	coord.SubmitTask("task-101", "RenderVideoSegment_1")
	coord.SubmitTask("task-102", "RenderVideoSegment_2")

	// Регистрируем воркеров
	coord.RegisterWorkerHeartbeat("worker-A")
	coord.RegisterWorkerHeartbeat("worker-B")

	coord.DispatchTasks()

	// Воркер B терпит сбой (нет heartbeat)
	fmt.Println("\n... Simulating Worker B crash (network down) ...")
	time.Sleep(1500 * time.Millisecond)

	// Воркер A продолжает жить
	coord.RegisterWorkerHeartbeat("worker-A")

	// Проверяем зависшие задачи с порогом 1 секунда
	coord.ReassignStaleTasks(1 * time.Second)

	// Повторное распределение
	coord.DispatchTasks()
}

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type Role string

const (
	RoleActive  Role = "ACTIVE"
	RoleStandby Role = "STANDBY"
)

type ClusterEvent struct {
	Type     string // "HEARTBEAT", "EXPIRED"
	LeaderID string
}

type FailoverNode struct {
	nodeID      string
	role        Role
	mu          sync.Mutex
	isCancelled atomic.Bool
}

func NewFailoverNode(id string, initialRole Role) *FailoverNode {
	return &FailoverNode{
		nodeID: id,
		role:   initialRole,
	}
}

func (n *FailoverNode) Run(ctx context.Context, bus chan ClusterEvent) {
	n.mu.Lock()
	currentRole := n.role
	n.mu.Unlock()

	if currentRole == RoleActive {
		n.runActive(ctx, bus)
	} else {
		n.runStandby(ctx, bus)
	}
}

func (n *FailoverNode) runActive(ctx context.Context, bus chan ClusterEvent) {
	ticker := time.NewTicker(800 * time.Millisecond)
	defer ticker.Stop()

	fmt.Printf("[%s] Started as ACTIVE leader. Emitting heartbeats...\n", n.nodeID)

	for {
		select {
		case <-ctx.Done():
			fmt.Printf("[%s] ACTIVE stopped. Graceful step down.\n", n.nodeID)
			bus <- ClusterEvent{Type: "EXPIRED", LeaderID: n.nodeID}
			return
		case <-ticker.C:
			if n.isCancelled.Load() {
				fmt.Printf("[%s] CRASH simulated! Ceasing heartbeats...\n", n.nodeID)
				return // Молча умираем, имитируя SIGKILL
			}
			bus <- ClusterEvent{Type: "HEARTBEAT", LeaderID: n.nodeID}
			fmt.Printf("[%s] Heartbeat sent.\n", n.nodeID)
		}
	}
}

func (n *FailoverNode) runStandby(ctx context.Context, bus chan ClusterEvent) {
	fmt.Printf("[%s] Started as STANDBY. Monitoring leader health...\n", n.nodeID)
	timeout := 2 * time.Second
	timer := time.NewTimer(timeout)
	defer timer.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case event := <-bus:
			if event.Type == "HEARTBEAT" {
				// Сбрасываем таймер при получении пульса
				if !timer.Stop() {
					select {
					case <-timer.C:
					default:
					}
				}
				timer.Reset(timeout)
			} else if event.Type == "EXPIRED" {
				fmt.Printf("[%s] Received explicit EXPIRED event. Promoting immediately!\n", n.nodeID)
				n.promoteToActive(ctx, bus)
				return
			}
		case <-timer.C:
			fmt.Printf("[%s] LEADER TIMEOUT! No heartbeat for %v. Promoting to ACTIVE!\n", n.nodeID, timeout)
			n.promoteToActive(ctx, bus)
			return
		}
	}
}

func (n *FailoverNode) promoteToActive(ctx context.Context, bus chan ClusterEvent) {
	n.mu.Lock()
	n.role = RoleActive
	n.mu.Unlock()
	fmt.Printf("[%s] >>> PROMOTION SUCCESSFUL. Node is now ACTIVE <<<\n", n.nodeID)
	n.runActive(ctx, bus)
}

func main() {
	eventBus := make(chan ClusterEvent, 10)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	activeNode := NewFailoverNode("pod-primary-0", RoleActive)
	standbyNode := NewFailoverNode("pod-standby-1", RoleStandby)

	go activeNode.Run(ctx, eventBus)
	go standbyNode.Run(ctx, eventBus)

	// Даем поработать в штатном режиме
	time.Sleep(2 * time.Second)

	// Симулируем внезапную смерть активного узла
	fmt.Println("\n>>> Triggering simulated crash on primary node <<<")
	activeNode.isCancelled.Store(true)

	// Ждем пока Standby обнаружит отсутствие пульса и промоутится
	time.Sleep(3 * time.Second)
	fmt.Println("Failover simulation complete.")
}

package main

import (
	"fmt"
	"sort"
	"sync"
	"sync/atomic"
)

type Proposal struct {
	CandidateID    string
	CreateRevision int64
	LeaseID        int64
}

type MockEtcdElection struct {
	mu          sync.Mutex
	prefix      string
	globalRev   atomic.Int64
	proposals   map[string]Proposal
	currentLead string
}

func NewMockEtcdElection(prefix string) *MockEtcdElection {
	e := &MockEtcdElection{
		prefix:    prefix,
		proposals: make(map[string]Proposal),
	}
	e.globalRev.Store(100) // Начальная ревизия etcd
	return e
}

func (e *MockEtcdElection) Campaign(candidateID string, leaseID int64) Proposal {
	e.mu.Lock()
	defer e.mu.Unlock()

	rev := e.globalRev.Add(1)
	p := Proposal{
		CandidateID:    candidateID,
		CreateRevision: rev,
		LeaseID:        leaseID,
	}
	e.proposals[candidateID] = p
	e.recalculateLeader()
	return p
}

func (e *MockEtcdElection) Resign(candidateID string) {
	e.mu.Lock()
	defer e.mu.Unlock()

	delete(e.proposals, candidateID)
	e.recalculateLeader()
}

func (e *MockEtcdElection) recalculateLeader() {
	if len(e.proposals) == 0 {
		e.currentLead = ""
		return
	}

	props := make([]Proposal, 0, len(e.proposals))
	for _, p := range e.proposals {
		props = append(props, p)
	}

	// Сортировка по возрастанию CreateRevision (детерминированный FIFO)
	sort.Slice(props, func(i, j int) bool {
		return props[i].CreateRevision < props[j].CreateRevision
	})

	e.currentLead = props[0].CandidateID
}

func (e *MockEtcdElection) GetLeader() (string, int64) {
	e.mu.Lock()
	defer e.mu.Unlock()
	if e.currentLead == "" {
		return "NONE", 0
	}
	return e.currentLead, e.proposals[e.currentLead].CreateRevision
}

func main() {
	election := NewMockEtcdElection("/services/payment-processor/leader")

	// Симулируем одновременный старт трех подов
	p1 := election.Campaign("pod-alpha", 0x1001)
	p2 := election.Campaign("pod-beta", 0x1002)
	p3 := election.Campaign("pod-gamma", 0x1003)

	fmt.Printf("Registered proposals:\n- %s (rev: %d)\n- %s (rev: %d)\n- %s (rev: %d)\n\n",
		p1.CandidateID, p1.CreateRevision,
		p2.CandidateID, p2.CreateRevision,
		p3.CandidateID, p3.CreateRevision)

	lead, rev := election.GetLeader()
	fmt.Printf("Elected Leader: %s (Key with lowest revision: %d)\n", lead, rev)

	// Узел alpha завершает работу
	fmt.Printf("\n>>> %s resigns (SIGTERM) <<<\n", lead)
	election.Resign("pod-alpha")

	lead2, rev2 := election.GetLeader()
	fmt.Printf("New Elected Leader: %s (Deterministic next revision: %d)\n", lead2, rev2)
}

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type LocalMetrics struct {
	NodeID       string
	Requests     int64
	Errors       int64
	CollectedAt  time.Time
}

type AggregatedSummary struct {
	TotalRequests int64
	TotalErrors   int64
	NodeCount     int
	Timestamp     time.Time
}

type MetricsCollector struct {
	mu          sync.Mutex
	isLeader    atomic.Bool
	buffer      map[string]LocalMetrics
	externalBus chan AggregatedSummary
}

func NewMetricsCollector() *MetricsCollector {
	return &MetricsCollector{
		buffer:      make(map[string]LocalMetrics),
		externalBus: make(chan AggregatedSummary, 5),
	}
}

func (c *MetricsCollector) SetLeader(leading bool) {
	c.isLeader.Store(leading)
}

func (c *MetricsCollector) Report(m LocalMetrics) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.buffer[m.NodeID] = m
}

func (c *MetricsCollector) Flush(ctx context.Context) error {
	if !c.isLeader.Load() {
		return fmt.Errorf("passive replica: external metric shipping is disabled")
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	var totalReq, totalErr int64
	for _, m := range c.buffer {
		totalReq += m.Requests
		totalErr += m.Errors
	}
	summary := AggregatedSummary{
		TotalRequests: totalReq,
		TotalErrors:   totalErr,
		NodeCount:     len(c.buffer),
		Timestamp:     time.Now(),
	}

	// Очищаем буфер после успешного объединения
	c.buffer = make(map[string]LocalMetrics)

	select {
	case c.externalBus <- summary:
		return nil
	default:
		return fmt.Errorf("external shipping channel buffer is full")
	}
}

func main() {
	collector := NewMetricsCollector()

	// Реплики отправляют свои данные
	collector.Report(LocalMetrics{NodeID: "worker-01", Requests: 1200, Errors: 4})
	collector.Report(LocalMetrics{NodeID: "worker-02", Requests: 3400, Errors: 1})
	collector.Report(LocalMetrics{NodeID: "worker-03", Requests: 2100, Errors: 0})

	// Попытка отправки узлом, пока он не лидер
	err := collector.Flush(context.Background())
	fmt.Printf("[Replica State] Flush attempt result: %v\n", err)

	// Узел становится лидером
	fmt.Println("\n>>> Node promoted to Leader <<<")
	collector.SetLeader(true)

	// Успешная агрегация и отправка
	if err := collector.Flush(context.Background()); err != nil {
		fmt.Printf("Flush error: %v\n", err)
	} else {
		summary := <-collector.externalBus
		fmt.Printf("[Leader Sent to External TSDB]: Nodes=%d, TotalRequests=%d, TotalErrors=%d at %s\n",
			summary.NodeCount, summary.TotalRequests, summary.TotalErrors, summary.Timestamp.Format("15:04:05"))
	}
}

package main

import (
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type MockHistogram struct {
	mu     sync.Mutex
	counts map[string]int
}

func NewMockHistogram() *MockHistogram {
	return &MockHistogram{counts: make(map[string]int)}
}

func (h *MockHistogram) Observe(seconds float64) {
	h.mu.Lock()
	defer h.mu.Unlock()
	bucket := "<= 1s"
	if seconds > 1.0 && seconds <= 5.0 {
		bucket = "<= 5s"
	} else if seconds > 5.0 {
		bucket = "> 5s"
	}
	h.counts[bucket]++
}

type LeaderMetrics struct {
	isLeader         atomic.Int64 // 1 or 0
	transitionsTotal atomic.Int64
	leaseDuration    *MockHistogram
	electedAt        time.Time
	mu               sync.Mutex
}

func NewLeaderMetrics() *LeaderMetrics {
	return &LeaderMetrics{
		leaseDuration: NewMockHistogram(),
	}
}

func (m *LeaderMetrics) RecordBecameLeader() {
	m.mu.Lock()
	defer m.mu.Unlock()

	m.isLeader.Store(1)
	m.transitionsTotal.Add(1)
	m.electedAt = time.Now()
	fmt.Println("[Metric Update] leader_election_is_leader = 1")
	fmt.Printf("[Metric Update] leader_election_transitions_total = %d\n", m.transitionsTotal.Load())
}

func (m *LeaderMetrics) RecordSteppedDown() {
	m.mu.Lock()
	defer m.mu.Unlock()

	if m.isLeader.Load() == 0 {
		return
	}

	m.isLeader.Store(0)
	duration := time.Since(m.electedAt).Seconds()
	m.leaseDuration.Observe(duration)

	fmt.Println("[Metric Update] leader_election_is_leader = 0")
	fmt.Printf("[Metric Update] leader_election_lease_duration_seconds observed: %.3fs\n", duration)
}

func (m *LeaderMetrics) PrintSummary() {
	m.mu.Lock()
	defer m.mu.Unlock()

	fmt.Println("\n=== PROMETHEUS METRIC DUMP ===")
	fmt.Printf("# TYPE leader_election_is_leader gauge\nleader_election_is_leader %d\n", m.isLeader.Load())
	fmt.Printf("# TYPE leader_election_transitions_total counter\nleader_election_transitions_total %d\n", m.transitionsTotal.Load())
	fmt.Println("# TYPE leader_election_lease_duration_seconds histogram")
	for bucket, count := range m.leaseDuration.counts {
		fmt.Printf("leader_election_lease_duration_seconds_bucket{le=\"%s\"} %d\n", bucket, count)
	}
}

func main() {
	metrics := NewLeaderMetrics()

	// 1-я кампания: узел побеждает, удерживает лидерство 1.2 секунды и сдает
	metrics.RecordBecameLeader()
	time.Sleep(1200 * time.Millisecond)
	metrics.RecordSteppedDown()

	// Пауза между выборами
	time.Sleep(200 * time.Millisecond)

	// 2-я кампания: повторное избрание на 600 миллисекунд
	metrics.RecordBecameLeader()
	time.Sleep(600 * time.Millisecond)
	metrics.RecordSteppedDown()

	metrics.PrintSummary()
}

package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

type SharedCacheStore struct {
	mu    sync.RWMutex
	items map[string]string
}

func (s *SharedCacheStore) Set(k, v string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.items[k] = v
}

func (s *SharedCacheStore) Get(k string) (string, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	val, ok := s.items[k]
	return val, ok
}

type CacheCoordinator struct {
	mu           sync.Mutex
	isWarmed     bool
	readyChannel chan struct{}
	store        *SharedCacheStore
}

func NewCacheCoordinator(store *SharedCacheStore) *CacheCoordinator {
	return &CacheCoordinator{
		readyChannel: make(chan struct{}),
		store:        store,
	}
}

func (c *CacheCoordinator) WarmUpAsLeader(ctx context.Context, nodeID string) error {
	fmt.Printf("[%s] LEADER: Starting cache pre-warming from primary DB...\n", nodeID)

	// Имитируем тяжелый прогрев таблиц
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-time.After(800 * time.Millisecond):
		c.store.Set("config:geo_zones", "EU,US,APAC")
		c.store.Set("config:fee_schedule", "tier_gold:0.01")
	}

	c.mu.Lock()
	c.isWarmed = true
	close(c.readyChannel)
	c.mu.Unlock()

	fmt.Printf("[%s] LEADER: Cache warming complete. Signalled followers via etcd event.\n", nodeID)
	return nil
}

func (c *CacheCoordinator) AwaitWarmup(ctx context.Context, nodeID string) error {
	fmt.Printf("[%s] FOLLOWER: Waiting for leader to complete cache warming...\n", nodeID)

	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-c.readyChannel:
		fmt.Printf("[%s] FOLLOWER: Cache ready signal received! Enabling K8s readiness probe.\n", nodeID)
		return nil
	case <-time.After(3 * time.Second):
		return errors.New("timeout waiting for cache warming")
	}
}

func main() {
	sharedStore := &SharedCacheStore{items: make(map[string]string)}
	coord := NewCacheCoordinator(sharedStore)

	var wg sync.WaitGroup

	// Запуск 2 фоловеров
	for _, fID := range []string{"pod-follower-1", "pod-follower-2"} {
		wg.Add(1)
		go func(id string) {
			defer wg.Done()
			if err := coord.AwaitWarmup(context.Background(), id); err != nil {
				fmt.Printf("[%s] Error: %v\n", id, err)
			}
		}(fID)
	}

	time.Sleep(100 * time.Millisecond)

	// Лидер запускает прогрев
	wg.Add(1)
	go func() {
		defer wg.Done()
		if err := coord.WarmUpAsLeader(context.Background(), "pod-leader-0"); err != nil {
			fmt.Printf("Leader warmup failed: %v\n", err)
		}
	}()

	wg.Wait()

	val, _ := sharedStore.Get("config:geo_zones")
	fmt.Printf("\nVerification: Cache content 'config:geo_zones' = %s\n", val)
}

package main

import (
	"context"
	"fmt"
	"sync/atomic"
	"time"
)

type DatabaseRecord struct {
	ID        int
	ExpiredAt time.Time
}

type MockDB struct {
	records []DatabaseRecord
}

func (db *MockDB) DeleteExpiredBatch(now time.Time, limit int) int {
	retained := make([]DatabaseRecord, 0, len(db.records))
	deleted := 0

	for _, r := range db.records {
		if deleted < limit && r.ExpiredAt.Before(now) {
			deleted++
		} else {
			retained = append(retained, r)
		}
	}
	db.records = retained
	return deleted
}

type LeaderGarbageCollector struct {
	nodeID    string
	isLeader  atomic.Bool
	batchSize int
	throttle  time.Duration
	db        *MockDB
}

func NewLeaderGarbageCollector(nodeID string, batchSize int, throttle time.Duration, db *MockDB) *LeaderGarbageCollector {
	return &LeaderGarbageCollector{
		nodeID:    nodeID,
		batchSize: batchSize,
		throttle:  throttle,
		db:        db,
	}
}

func (c *LeaderGarbageCollector) SetLeader(leading bool) {
	c.isLeader.Store(leading)
}

func (c *LeaderGarbageCollector) RunCleanup(ctx context.Context) (int, error) {
	if !c.isLeader.Load() {
		return 0, fmt.Errorf("[%s] Not a leader: skipping GC cycle", c.nodeID)
	}

	totalDeleted := 0
	fmt.Printf("[%s] LEADER GC: Starting batched cleanup loop (batchSize=%d)...\n", c.nodeID, c.batchSize)

	for {
		select {
		case <-ctx.Done():
			return totalDeleted, ctx.Err()
		default:
		}

		// Проверяем статус лидера перед каждым пакетом
		if !c.isLeader.Load() {
			fmt.Printf("[%s] Leadership lost mid-cleanup! Halting operations.\n", c.nodeID)
			return totalDeleted, nil
		}

		deleted := c.db.DeleteExpiredBatch(time.Now(), c.batchSize)
		totalDeleted += deleted

		if deleted > 0 {
			fmt.Printf("[%s] Deleted chunk of %d expired records. Sleeping %v for DB throttle...\n",
				c.nodeID, deleted, c.throttle)
		}

		if deleted < c.batchSize {
			// Все устаревшие записи удалены
			break
		}

		time.Sleep(c.throttle)
	}

	fmt.Printf("[%s] LEADER GC: Completed. Total purged: %d\n", c.nodeID, totalDeleted)
	return totalDeleted, nil
}

func main() {
	now := time.Now()
	// Создаем базу данных с 15 просроченными записями
	records := make([]DatabaseRecord, 15)
	for i := 0; i < 15; i++ {
		records[i] = DatabaseRecord{
			ID:        i + 1,
			ExpiredAt: now.Add(-1 * time.Hour),
		}
	}

	db := &MockDB{records: records}
	gc := NewLeaderGarbageCollector("worker-pod-0", 5, 50*time.Millisecond, db)

	// Запуск в роли фоловера
	_, err := gc.RunCleanup(context.Background())
	fmt.Printf("Initial run result: %v\n\n", err)

	// Получение лидерства и запуск порционной очистки
	gc.SetLeader(true)
	purged, _ := gc.RunCleanup(context.Background())
	fmt.Printf("Final verification: Purged %d records, remaining in DB: %d\n", purged, len(db.records))
}

